def tree_size(root,skip_browser=False):
 total=0;allocated=0
 if not root.exists():return {'bytes':0,'allocated_bytes':0}
 for base,dirs,names in os.walk(root,followlinks=False):
  dirs[:]=[d for d in dirs if not (pathlib.Path(base)/d).is_symlink() and not (skip_browser and pathlib.Path(base)==root and d=='browser')]
  for name in names:
   p=pathlib.Path(base)/name
   if p.is_symlink():continue
   s=p.stat()
   if stat.S_ISREG(s.st_mode):total+=s.st_size;allocated+=s.st_blocks*512
 return {'bytes':total,'allocated_bytes':allocated}
